        blockId: 'unknown',
        blockName: 'unknown',
        data: mem.data,
      }
    } else {
      const { conversationId, blockId } = parsed
      const blockName = (await getBlockName(blockId, validatedWorkflowId)) || 'unknown'

      enrichedMemory = {
        conversationId,
        blockId,
