const defaultSettings = {
  theme: 'system',
  autoConnect: true,
  telemetryEnabled: true,
  emailPreferences: {},
  billingUsageNotificationsEnabled: true,
  showTrainingControls: false,
  superUserModeEnabled: false,
  errorNotificationsEnabled: true,
