/**
 * Perform bulk operations on documents
 */
export async function bulkDocumentOperation(
  knowledgeBaseId: string,
  operation: 'enable' | 'disable' | 'delete',
  documentIds: string[],
  requestId: string,
  userId?: string
): Promise<{
  success: boolean
  successCount: number
  updatedDocuments: Array<{
    id: string
    enabled?: boolean
    deletedAt?: Date | null
    processingStatus?: string
  }>
}> {
  logger.info(
    `[${requestId}] Starting bulk ${operation} operation on ${documentIds.length} documents in knowledge base ${knowledgeBaseId}`
  )

  // Verify all documents belong to this knowledge base
  const documentsToUpdate = await db
    .select({
      id: document.id,
      enabled: document.enabled,
    })
    .from(document)
    .where(
      and(
        eq(document.knowledgeBaseId, knowledgeBaseId),
        inArray(document.id, documentIds),
        isNull(document.deletedAt)
      )
    )

  if (documentsToUpdate.length === 0) {
    throw new Error('No valid documents found to update')
  }

  if (documentsToUpdate.length !== documentIds.length) {
    logger.warn(
      `[${requestId}] Some documents not found or don't belong to knowledge base. Requested: ${documentIds.length}, Found: ${documentsToUpdate.length}`
    )
  }

  let updateResult: Array<{
    id: string
    enabled?: boolean
    deletedAt?: Date | null
    processingStatus?: string
  }>

  if (operation === 'delete') {
    // Get file sizes before deletion for storage tracking
    let totalSize = 0
    if (userId) {
      const documentsToDelete = await db
        .select({ fileSize: document.fileSize })
        .from(document)
        .where(
          and(
            eq(document.knowledgeBaseId, knowledgeBaseId),
            inArray(document.id, documentIds),
            isNull(document.deletedAt)
          )
        )

      totalSize = documentsToDelete.reduce((sum, doc) => sum + doc.fileSize, 0)
    }

    // Handle bulk soft delete
    updateResult = await db
      .update(document)
      .set({
        deletedAt: new Date(),
      })
      .where(
        and(
          eq(document.knowledgeBaseId, knowledgeBaseId),
          inArray(document.id, documentIds),
          isNull(document.deletedAt)
        )
      )
      .returning({ id: document.id, deletedAt: document.deletedAt })
  } else {
    // Handle bulk enable/disable
    const enabled = operation === 'enable'

    updateResult = await db
      .update(document)
      .set({
        enabled,
      })
      .where(
        and(
          eq(document.knowledgeBaseId, knowledgeBaseId),
          inArray(document.id, documentIds),
          isNull(document.deletedAt)
        )
      )
      .returning({ id: document.id, enabled: document.enabled })
  }

  const successCount = updateResult.length

  logger.info(
    `[${requestId}] Bulk ${operation} operation completed: ${successCount} documents updated in knowledge base ${knowledgeBaseId}`
  )

  return {
    success: true,
    successCount,
    updatedDocuments: updateResult,
  }
}

/**
 * Mark a document as failed due to timeout
 */
export async function markDocumentAsFailedTimeout(
  documentId: string,
  processingStartedAt: Date,
  requestId: string
): Promise<{ success: boolean; processingDuration: number }> {
  const now = new Date()
  const processingDuration = now.getTime() - processingStartedAt.getTime()
  const DEAD_PROCESS_THRESHOLD_MS = 600 * 1000 // 10 minutes

  if (processingDuration <= DEAD_PROCESS_THRESHOLD_MS) {
    throw new Error('Document has not been processing long enough to be considered dead')
  }

  await db
    .update(document)
    .set({
      processingStatus: 'failed',
      processingError: 'Processing timed out - background process may have been terminated',
      processingCompletedAt: now,
    })
    .where(eq(document.id, documentId))

  logger.info(
    `[${requestId}] Marked document ${documentId} as failed due to dead process (processing time: ${Math.round(processingDuration / 1000)}s)`
  )

  return {
    success: true,
    processingDuration,
  }
}

/**
 * Retry processing a failed document
 */
export async function retryDocumentProcessing(
  knowledgeBaseId: string,
  documentId: string,
  docData: {
    filename: string
    fileUrl: string
    fileSize: number
    mimeType: string
  },
  requestId: string
): Promise<{ success: boolean; status: string; message: string }> {
  // Clear existing embeddings and reset document state
  await db.transaction(async (tx) => {
    await tx.delete(embedding).where(eq(embedding.documentId, documentId))

    await tx
      .update(document)
      .set({
        processingStatus: 'pending',
        processingStartedAt: null,
        processingCompletedAt: null,
        processingError: null,
        chunkCount: 0,
        tokenCount: 0,
        characterCount: 0,
      })
      .where(eq(document.id, documentId))
  })

  const processingOptions = {
    chunkSize: 512,
    minCharactersPerChunk: 24,
    recipe: 'default',
    lang: 'en',
    chunkOverlap: 100,
  }

  // Start processing in the background
  processDocumentAsync(knowledgeBaseId, documentId, docData, processingOptions).catch(
    (error: unknown) => {
      logger.error(`[${requestId}] Background retry processing error:`, error)
    }
  )

  logger.info(`[${requestId}] Document retry initiated: ${documentId}`)

  return {
    success: true,
    status: 'pending',
    message: 'Document retry processing started',
  }
}

/**
 * Update a document with specified fields
 */
export async function updateDocument(
  documentId: string,
  updateData: {
    filename?: string
    enabled?: boolean
    chunkCount?: number
    tokenCount?: number
    characterCount?: number
    processingStatus?: 'pending' | 'processing' | 'completed' | 'failed'
    processingError?: string
    // Text tags
    tag1?: string
    tag2?: string
    tag3?: string
    tag4?: string
    tag5?: string
    tag6?: string
    tag7?: string
    // Number tags
    number1?: string
    number2?: string
    number3?: string
    number4?: string
    number5?: string
    // Date tags
    date1?: string
    date2?: string
    // Boolean tags
    boolean1?: string
    boolean2?: string
    boolean3?: string
  },
  requestId: string
): Promise<{
  id: string
  knowledgeBaseId: string
  filename: string
  fileUrl: string
  fileSize: number
  mimeType: string
  chunkCount: number
  tokenCount: number
  characterCount: number
  processingStatus: 'pending' | 'processing' | 'completed' | 'failed'
  processingStartedAt: Date | null
  processingCompletedAt: Date | null
  processingError: string | null
  enabled: boolean
  uploadedAt: Date
  tag1: string | null
  tag2: string | null
  tag3: string | null
  tag4: string | null
  tag5: string | null
  tag6: string | null
  tag7: string | null
  number1: number | null
  number2: number | null
  number3: number | null
  number4: number | null
  number5: number | null
  date1: Date | null
  date2: Date | null
  boolean1: boolean | null
  boolean2: boolean | null
  boolean3: boolean | null
  deletedAt: Date | null
}> {
  const dbUpdateData: Partial<{
    filename: string
    enabled: boolean
    chunkCount: number
    tokenCount: number
    characterCount: number
    processingStatus: 'pending' | 'processing' | 'completed' | 'failed'
    processingError: string | null
    processingStartedAt: Date | null
    processingCompletedAt: Date | null
    tag1: string | null
    tag2: string | null
    tag3: string | null
    tag4: string | null
    tag5: string | null
    tag6: string | null
    tag7: string | null
    number1: number | null
    number2: number | null
    number3: number | null
    number4: number | null
    number5: number | null
    date1: Date | null
    date2: Date | null
    boolean1: boolean | null
    boolean2: boolean | null
    boolean3: boolean | null
  }> = {}
  // All tag slots across all field types
  const ALL_TAG_SLOTS = [
    'tag1',
    'tag2',
    'tag3',
    'tag4',
    'tag5',
    'tag6',
    'tag7',
    'number1',
    'number2',
    'number3',
    'number4',
    'number5',
    'date1',
    'date2',
    'boolean1',
    'boolean2',
    'boolean3',
  ] as const
  type TagSlot = (typeof ALL_TAG_SLOTS)[number]

  // Regular field updates
  if (updateData.filename !== undefined) dbUpdateData.filename = updateData.filename
  if (updateData.enabled !== undefined) dbUpdateData.enabled = updateData.enabled
  if (updateData.chunkCount !== undefined) dbUpdateData.chunkCount = updateData.chunkCount
  if (updateData.tokenCount !== undefined) dbUpdateData.tokenCount = updateData.tokenCount
  if (updateData.characterCount !== undefined)
    dbUpdateData.characterCount = updateData.characterCount
  if (updateData.processingStatus !== undefined)
    dbUpdateData.processingStatus = updateData.processingStatus
  if (updateData.processingError !== undefined)
    dbUpdateData.processingError = updateData.processingError

  // Helper to convert string values to proper types for the database
  const convertTagValue = (
    slot: string,
    value: string | undefined
  ): string | number | Date | boolean | null => {
    if (value === undefined || value === '') return null

    // Number slots
    if (slot.startsWith('number')) {
      return parseNumberValue(value)
    }

    // Date slots
    if (slot.startsWith('date')) {
      return parseDateValue(value)
    }

    // Boolean slots
    if (slot.startsWith('boolean')) {
      return parseBooleanValue(value) ?? false
    }

    // Text slots: keep as string
    return value || null
  }

  ALL_TAG_SLOTS.forEach((slot: TagSlot) => {
    const updateValue = (updateData as any)[slot]
    if (updateValue !== undefined) {
      ;(dbUpdateData as any)[slot] = convertTagValue(slot, updateValue)
    }
  })

  await db.transaction(async (tx) => {
    await tx.update(document).set(dbUpdateData).where(eq(document.id, documentId))

    const hasTagUpdates = ALL_TAG_SLOTS.some((field) => (updateData as any)[field] !== undefined)

    if (hasTagUpdates) {
      const embeddingUpdateData: Record<string, any> = {}
      ALL_TAG_SLOTS.forEach((field) => {
        if ((updateData as any)[field] !== undefined) {
          embeddingUpdateData[field] = convertTagValue(field, (updateData as any)[field])
        }
      })

      await tx
        .update(embedding)
        .set(embeddingUpdateData)
        .where(eq(embedding.documentId, documentId))
    }
  })

  const updatedDocument = await db
    .select()
    .from(document)
    .where(eq(document.id, documentId))
    .limit(1)

  if (updatedDocument.length === 0) {
    throw new Error(`Document ${documentId} not found`)
  }

  logger.info(`[${requestId}] Document updated: ${documentId}`)

  const doc = updatedDocument[0]
  return {
    id: doc.id,
    knowledgeBaseId: doc.knowledgeBaseId,
    filename: doc.filename,
    fileUrl: doc.fileUrl,
    fileSize: doc.fileSize,
    mimeType: doc.mimeType,
    chunkCount: doc.chunkCount,
    tokenCount: doc.tokenCount,
    characterCount: doc.characterCount,
    processingStatus: doc.processingStatus as 'pending' | 'processing' | 'completed' | 'failed',
    processingStartedAt: doc.processingStartedAt,
    processingCompletedAt: doc.processingCompletedAt,
    processingError: doc.processingError,
    enabled: doc.enabled,
    uploadedAt: doc.uploadedAt,
    tag1: doc.tag1,
    tag2: doc.tag2,
    tag3: doc.tag3,
    tag4: doc.tag4,
    tag5: doc.tag5,
    tag6: doc.tag6,
    tag7: doc.tag7,
    number1: doc.number1,
    number2: doc.number2,
    number3: doc.number3,
    number4: doc.number4,
    number5: doc.number5,
    date1: doc.date1,
    date2: doc.date2,
    boolean1: doc.boolean1,
    boolean2: doc.boolean2,
    boolean3: doc.boolean3,
    deletedAt: doc.deletedAt,
  }
}

/**
 * Soft delete a document
 */
export async function deleteDocument(
  documentId: string,
  requestId: string
): Promise<{ success: boolean; message: string }> {
  await db
    .update(document)
    .set({
      deletedAt: new Date(),
    })
    .where(eq(document.id, documentId))

  logger.info(`[${requestId}] Document deleted: ${documentId}`)

  return {
    success: true,
    message: 'Document deleted successfully',
  }
}

import { document, embedding } from '@sim/db/schema'
import { and, eq, gt, gte, ilike, lt, lte, ne, not, or, type SQL } from 'drizzle-orm'
import type {
  BooleanFilterCondition,
  DateFilterCondition,
  FilterCondition,
  FilterGroup,
  NumberFilterCondition,
  SimpleTagFilter,
  TagFilter,
  TextFilterCondition,
} from './types'

/**
 * Valid tag slots that can be used in filters
 */
const VALID_TEXT_SLOTS = ['tag1', 'tag2', 'tag3', 'tag4', 'tag5', 'tag6', 'tag7'] as const
const VALID_NUMBER_SLOTS = ['number1', 'number2', 'number3', 'number4', 'number5'] as const
const VALID_DATE_SLOTS = ['date1', 'date2'] as const
const VALID_BOOLEAN_SLOTS = ['boolean1', 'boolean2', 'boolean3'] as const

type TextSlot = (typeof VALID_TEXT_SLOTS)[number]
type NumberSlot = (typeof VALID_NUMBER_SLOTS)[number]
type DateSlot = (typeof VALID_DATE_SLOTS)[number]
type BooleanSlot = (typeof VALID_BOOLEAN_SLOTS)[number]

/**
 * Validates that a tag slot is valid for the given field type
 */
function isValidSlotForType(
  slot: string,
  fieldType: string
): slot is TextSlot | NumberSlot | DateSlot | BooleanSlot {
  switch (fieldType) {
    case 'text':
      return (VALID_TEXT_SLOTS as readonly string[]).includes(slot)
    case 'number':
      return (VALID_NUMBER_SLOTS as readonly string[]).includes(slot)
    case 'date':
      return (VALID_DATE_SLOTS as readonly string[]).includes(slot)
    case 'boolean':
      return (VALID_BOOLEAN_SLOTS as readonly string[]).includes(slot)
    default:
      return false
  }
}

/**
 * Build SQL condition for a text filter
 */
function buildTextCondition(
  condition: TextFilterCondition,
  table: typeof document | typeof embedding
): SQL | null {
  const { tagSlot, operator, value } = condition

  if (!isValidSlotForType(tagSlot, 'text')) {
    return null
  }

  const column = table[tagSlot as TextSlot]
  if (!column) return null

  switch (operator) {
    case 'eq':
      return eq(column, value)
    case 'neq':
      return ne(column, value)
    case 'contains':
      return ilike(column, `%${value}%`)
    case 'not_contains':
      return not(ilike(column, `%${value}%`))
    case 'starts_with':
      return ilike(column, `${value}%`)
    case 'ends_with':
      return ilike(column, `%${value}`)
    default:
      return null
  }
}

/**
 * Build SQL condition for a number filter
 */
function buildNumberCondition(
  condition: NumberFilterCondition,
  table: typeof document | typeof embedding
): SQL | null {
  const { tagSlot, operator, value, valueTo } = condition

  if (!isValidSlotForType(tagSlot, 'number')) {
    return null
  }

  const column = table[tagSlot as NumberSlot]
  if (!column) return null

  switch (operator) {
    case 'eq':
      return eq(column, value)
    case 'neq':
      return ne(column, value)
    case 'gt':
      return gt(column, value)
    case 'gte':
      return gte(column, value)
    case 'lt':
      return lt(column, value)
    case 'lte':
      return lte(column, value)
    case 'between':
      if (valueTo !== undefined) {
        return and(gte(column, value), lte(column, valueTo)) ?? null
      }
      return null
    default:
      return null
  }
}

/**
 * Parse a YYYY-MM-DD date string into a UTC Date object.
 */
function parseDateValue(value: string): Date | null {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return null
  const [year, month, day] = value.split('-').map(Number)
  return new Date(Date.UTC(year, month - 1, day))
}

/**
 * Build SQL condition for a date filter.
 * Expects date values in YYYY-MM-DD format.
 */
function buildDateCondition(
  condition: DateFilterCondition,
  table: typeof document | typeof embedding
): SQL | null {
  const { tagSlot, operator, value, valueTo } = condition

  if (!isValidSlotForType(tagSlot, 'date')) {
    return null
  }

  const column = table[tagSlot as DateSlot]
  if (!column) return null

  const dateValue = parseDateValue(value)
  if (!dateValue) return null

  switch (operator) {
    case 'eq':
      return eq(column, dateValue)
    case 'neq':
      return ne(column, dateValue)
    case 'gt':
      return gt(column, dateValue)
    case 'gte':
      return gte(column, dateValue)
    case 'lt':
      return lt(column, dateValue)
    case 'lte':
      return lte(column, dateValue)
    case 'between':
      if (valueTo !== undefined) {
        const dateValueTo = parseDateValue(valueTo)
        if (!dateValueTo) return null
        return and(gte(column, dateValue), lte(column, dateValueTo)) ?? null
      }
      return null
    default:
      return null
  }
}

/**
 * Build SQL condition for a boolean filter
 */
function buildBooleanCondition(
  condition: BooleanFilterCondition,
  table: typeof document | typeof embedding
): SQL | null {
  const { tagSlot, operator, value } = condition

  if (!isValidSlotForType(tagSlot, 'boolean')) {
    return null
  }

  const column = table[tagSlot as BooleanSlot]
  if (!column) return null

  switch (operator) {
    case 'eq':
      return eq(column, value)
    case 'neq':
      return ne(column, value)
    default:
      return null
  }
}

/**
 * Build SQL condition for a single filter condition
 */
function buildCondition(
  condition: FilterCondition,
  table: typeof document | typeof embedding
): SQL | null {
  switch (condition.fieldType) {
    case 'text':
      return buildTextCondition(condition, table)
    case 'number':
      return buildNumberCondition(condition, table)
    case 'date':
      return buildDateCondition(condition, table)
    case 'boolean':
      return buildBooleanCondition(condition, table)
    default:
      return null
  }
}

/**
 * Build SQL condition for a filter group
 */
function buildGroupCondition(
  group: FilterGroup,
  table: typeof document | typeof embedding
): SQL | null {
  const conditions = group.conditions
    .map((condition) => buildCondition(condition, table))
    .filter((c): c is SQL => c !== null)

  if (conditions.length === 0) {
    return null
  }

  if (conditions.length === 1) {
    return conditions[0]
  }

  return (group.operator === 'AND' ? and(...conditions) : or(...conditions)) ?? null
}

/**
 * Build SQL WHERE clause from a TagFilter
 * Supports nested groups with AND/OR logic
 */
export function buildTagFilterQuery(
  filter: TagFilter,
  table: typeof document | typeof embedding
): SQL | null {
  const groupConditions = filter.groups
    .map((group) => buildGroupCondition(group, table))
    .filter((c): c is SQL => c !== null)

  if (groupConditions.length === 0) {
    return null
  }

  if (groupConditions.length === 1) {
    return groupConditions[0]
  }

  return (filter.rootOperator === 'AND' ? and(...groupConditions) : or(...groupConditions)) ?? null
}

/**
 * Build SQL WHERE clause from a SimpleTagFilter
 * For flat filter structures without nested groups
 */
export function buildSimpleTagFilterQuery(
  filter: SimpleTagFilter,
  table: typeof document | typeof embedding
): SQL | null {
  const conditions = filter.conditions
    .map((condition) => buildCondition(condition, table))
    .filter((c): c is SQL => c !== null)

  if (conditions.length === 0) {
    return null
  }

  if (conditions.length === 1) {
    return conditions[0]
  }

  return (filter.operator === 'AND' ? and(...conditions) : or(...conditions)) ?? null
}

/**
 * Build SQL WHERE clause from an array of filter conditions
 * Combines all conditions with AND by default
 */
export function buildFilterConditionsQuery(
  conditions: FilterCondition[],
  table: typeof document | typeof embedding,
  operator: 'AND' | 'OR' = 'AND'
): SQL | null {
  return buildSimpleTagFilterQuery({ operator, conditions }, table)
}

/**
 * Convenience function to build filter for document table
 */
export function buildDocumentFilterQuery(filter: TagFilter | SimpleTagFilter): SQL | null {
  if ('rootOperator' in filter) {
    return buildTagFilterQuery(filter, document)
  }
  return buildSimpleTagFilterQuery(filter, document)
}

/**
 * Convenience function to build filter for embedding table
 */
export function buildEmbeddingFilterQuery(filter: TagFilter | SimpleTagFilter): SQL | null {
  if ('rootOperator' in filter) {
    return buildTagFilterQuery(filter, embedding)
  }
  return buildSimpleTagFilterQuery(filter, embedding)
}

/**
 * Validate a filter condition
 * Returns an array of validation errors, empty if valid
 */
export function validateFilterCondition(condition: FilterCondition): string[] {
  const errors: string[] = []

  if (!isValidSlotForType(condition.tagSlot, condition.fieldType)) {
    errors.push(`Invalid tag slot "${condition.tagSlot}" for field type "${condition.fieldType}"`)
  }

  switch (condition.fieldType) {
    case 'text':
      if (typeof condition.value !== 'string') {
        errors.push('Text filter value must be a string')
      }
      break
    case 'number':
      if (typeof condition.value !== 'number' || Number.isNaN(condition.value)) {
        errors.push('Number filter value must be a valid number')
      }
      if (condition.operator === 'between' && condition.valueTo === undefined) {
        errors.push('Between operator requires a second value')
      }
      if (condition.valueTo !== undefined && typeof condition.valueTo !== 'number') {
        errors.push('Number filter second value must be a valid number')
      }
      break
    case 'date':
      if (typeof condition.value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(condition.value)) {
        errors.push('Date filter value must be in YYYY-MM-DD format')
      }
      if (condition.operator === 'between' && condition.valueTo === undefined) {
        errors.push('Between operator requires a second value')
      }
      if (
        condition.valueTo !== undefined &&
        (typeof condition.valueTo !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(condition.valueTo))
      ) {
        errors.push('Date filter second value must be in YYYY-MM-DD format')
      }
      break
    case 'boolean':
      if (typeof condition.value !== 'boolean') {
        errors.push('Boolean filter value must be true or false')
      }
      break
  }

  return errors
}

/**
 * Validate all conditions in a filter
 */
export function validateFilter(filter: TagFilter | SimpleTagFilter): string[] {
  const errors: string[] = []

  if ('rootOperator' in filter) {
    for (const group of filter.groups) {
      for (const condition of group.conditions) {
        errors.push(...validateFilterCondition(condition))
      }
    }
  } else {
    for (const condition of filter.conditions) {
      errors.push(...validateFilterCondition(condition))
    }
  }

  return errors
}

import { randomUUID } from 'crypto'
import { db } from '@sim/db'
import { document, embedding, knowledgeBaseTagDefinitions } from '@sim/db/schema'
import { and, eq, isNotNull, isNull, sql } from 'drizzle-orm'
import { getSlotsForFieldType, SUPPORTED_FIELD_TYPES } from '@/lib/knowledge/constants'
import type { BulkTagDefinitionsData, DocumentTagDefinition } from '@/lib/knowledge/tags/types'
import type {
  CreateTagDefinitionData,
  TagDefinition,
  UpdateTagDefinitionData,
} from '@/lib/knowledge/types'
import { createLogger } from '@/lib/logs/console/logger'

const logger = createLogger('TagsService')

/** Text tag slots */
const VALID_TEXT_SLOTS = ['tag1', 'tag2', 'tag3', 'tag4', 'tag5', 'tag6', 'tag7'] as const

const VALID_NUMBER_SLOTS = ['number1', 'number2', 'number3', 'number4', 'number5'] as const
/** Date tag slots (reduced to 2 for write performance) */
const VALID_DATE_SLOTS = ['date1', 'date2'] as const
/** Boolean tag slots */
const VALID_BOOLEAN_SLOTS = ['boolean1', 'boolean2', 'boolean3'] as const

/** All valid tag slots combined */
const VALID_TAG_SLOTS = [
  ...VALID_TEXT_SLOTS,
  ...VALID_NUMBER_SLOTS,
  ...VALID_DATE_SLOTS,
  ...VALID_BOOLEAN_SLOTS,
] as const

type ValidTagSlot = (typeof VALID_TAG_SLOTS)[number]

/**
 * Validates that a tag slot is a valid slot name
 */
function validateTagSlot(tagSlot: string): asserts tagSlot is ValidTagSlot {
  if (!VALID_TAG_SLOTS.includes(tagSlot as ValidTagSlot)) {
    throw new Error(`Invalid tag slot: ${tagSlot}. Must be one of: ${VALID_TAG_SLOTS.join(', ')}`)
  }
}

/**
 * Get the field type for a tag slot
 */
function getFieldTypeForSlot(tagSlot: string): string | null {
  if ((VALID_TEXT_SLOTS as readonly string[]).includes(tagSlot)) return 'text'
  if ((VALID_NUMBER_SLOTS as readonly string[]).includes(tagSlot)) return 'number'
  if ((VALID_DATE_SLOTS as readonly string[]).includes(tagSlot)) return 'date'
  if ((VALID_BOOLEAN_SLOTS as readonly string[]).includes(tagSlot)) return 'boolean'
  return null
}

/**
 * Get the next available slot for a knowledge base and field type
 */
export async function getNextAvailableSlot(
  knowledgeBaseId: string,
  fieldType: string,
  existingBySlot?: Map<string, any>
): Promise<string | null> {
  const availableSlots = getSlotsForFieldType(fieldType)
  let usedSlots: Set<string>

  if (existingBySlot) {
    usedSlots = new Set(
      Array.from(existingBySlot.entries())
        .filter(([_, def]) => def.fieldType === fieldType)
        .map(([slot, _]) => slot)
    )
  } else {
    const existingDefinitions = await db
      .select({ tagSlot: knowledgeBaseTagDefinitions.tagSlot })
      .from(knowledgeBaseTagDefinitions)
      .where(
        and(
          eq(knowledgeBaseTagDefinitions.knowledgeBaseId, knowledgeBaseId),
          eq(knowledgeBaseTagDefinitions.fieldType, fieldType)
        )
      )

    usedSlots = new Set(existingDefinitions.map((def) => def.tagSlot))
  }

  for (const slot of availableSlots) {
    if (!usedSlots.has(slot)) {
      return slot
    }
  }

  return null // All slots for this field type are used
}

/**
 * Get all tag definitions for a knowledge base
 */
export async function getDocumentTagDefinitions(
  knowledgeBaseId: string
): Promise<DocumentTagDefinition[]> {
  const definitions = await db
    .select({
      id: knowledgeBaseTagDefinitions.id,
      knowledgeBaseId: knowledgeBaseTagDefinitions.knowledgeBaseId,
      tagSlot: knowledgeBaseTagDefinitions.tagSlot,
      displayName: knowledgeBaseTagDefinitions.displayName,
      fieldType: knowledgeBaseTagDefinitions.fieldType,
      createdAt: knowledgeBaseTagDefinitions.createdAt,
      updatedAt: knowledgeBaseTagDefinitions.updatedAt,
    })
    .from(knowledgeBaseTagDefinitions)
    .where(eq(knowledgeBaseTagDefinitions.knowledgeBaseId, knowledgeBaseId))
    .orderBy(knowledgeBaseTagDefinitions.tagSlot)

  return definitions.map((def) => ({
    ...def,
    tagSlot: def.tagSlot as string,
  }))
}

/**
 * Get all tag definitions for a knowledge base (alias for compatibility)
 */
export async function getTagDefinitions(knowledgeBaseId: string): Promise<TagDefinition[]> {
  const tagDefinitions = await db
    .select({
      id: knowledgeBaseTagDefinitions.id,
      tagSlot: knowledgeBaseTagDefinitions.tagSlot,
      displayName: knowledgeBaseTagDefinitions.displayName,
      fieldType: knowledgeBaseTagDefinitions.fieldType,
      createdAt: knowledgeBaseTagDefinitions.createdAt,
      updatedAt: knowledgeBaseTagDefinitions.updatedAt,
    })
    .from(knowledgeBaseTagDefinitions)
    .where(eq(knowledgeBaseTagDefinitions.knowledgeBaseId, knowledgeBaseId))
    .orderBy(knowledgeBaseTagDefinitions.tagSlot)

  return tagDefinitions.map((def) => ({
    ...def,
    tagSlot: def.tagSlot as string,
  }))
}

/**
 * Create or update tag definitions in bulk
 */
export async function createOrUpdateTagDefinitionsBulk(
  knowledgeBaseId: string,
  bulkData: BulkTagDefinitionsData,
  requestId: string
): Promise<{
  created: DocumentTagDefinition[]
  updated: DocumentTagDefinition[]
  errors: string[]
}> {
  const { definitions } = bulkData
  const created: DocumentTagDefinition[] = []
  const updated: DocumentTagDefinition[] = []
  const errors: string[] = []

  // Get existing definitions to check for conflicts and determine operations
  const existingDefinitions = await getDocumentTagDefinitions(knowledgeBaseId)
  const existingBySlot = new Map(existingDefinitions.map((def) => [def.tagSlot, def]))
  const existingByDisplayName = new Map(existingDefinitions.map((def) => [def.displayName, def]))

  // Process each definition
  for (const defData of definitions) {
    try {
      const { tagSlot, displayName, fieldType, originalDisplayName } = defData

      // Validate field type
      if (!SUPPORTED_FIELD_TYPES.includes(fieldType as (typeof SUPPORTED_FIELD_TYPES)[number])) {
        errors.push(`Invalid field type: ${fieldType}`)
        continue
      }

      // Check if this is an update (has originalDisplayName) or create
      const isUpdate = !!originalDisplayName

      if (isUpdate) {
        // Update existing definition
        const existingDef = existingByDisplayName.get(originalDisplayName!)
        if (!existingDef) {
          errors.push(`Tag definition with display name "${originalDisplayName}" not found`)
          continue
        }

        // Check if new display name conflicts with another definition
        if (displayName !== originalDisplayName && existingByDisplayName.has(displayName)) {
          errors.push(`Display name "${displayName}" already exists`)
          continue
        }

        const now = new Date()
        await db
          .update(knowledgeBaseTagDefinitions)
          .set({
            displayName,
            fieldType,
            updatedAt: now,
          })
          .where(eq(knowledgeBaseTagDefinitions.id, existingDef.id))

        updated.push({
          id: existingDef.id,
          knowledgeBaseId,
          tagSlot: existingDef.tagSlot,
          displayName,
          fieldType,
          createdAt: existingDef.createdAt,
          updatedAt: now,
        })
      } else {
        // Create new definition
        let finalTagSlot = tagSlot

        // If no slot provided or slot is taken, find next available
        if (!finalTagSlot || existingBySlot.has(finalTagSlot)) {
          const nextSlot = await getNextAvailableSlot(knowledgeBaseId, fieldType, existingBySlot)
          if (!nextSlot) {
            errors.push(`No available slots for field type "${fieldType}"`)
            continue
          }
          finalTagSlot = nextSlot
        }

        // Check slot conflicts
        if (existingBySlot.has(finalTagSlot)) {
          errors.push(`Tag slot "${finalTagSlot}" is already in use`)
          continue
        }

        // Check display name conflicts
        if (existingByDisplayName.has(displayName)) {
          errors.push(`Display name "${displayName}" already exists`)
          continue
        }

        const id = randomUUID()
        const now = new Date()

        const newDefinition = {
          id,
          knowledgeBaseId,
          tagSlot: finalTagSlot as ValidTagSlot,
          displayName,
          fieldType,
          createdAt: now,
          updatedAt: now,
        }

        await db.insert(knowledgeBaseTagDefinitions).values(newDefinition)

        // Add to maps to track for subsequent definitions in this batch
        existingBySlot.set(finalTagSlot, newDefinition)
        existingByDisplayName.set(displayName, newDefinition)

        created.push(newDefinition as DocumentTagDefinition)
      }
    } catch (error) {
      errors.push(`Error processing definition "${defData.displayName}": ${error}`)
    }
  }

  logger.info(
    `[${requestId}] Bulk tag definitions processed: ${created.length} created, ${updated.length} updated, ${errors.length} errors`
  )

  return { created, updated, errors }
}

/**
 * Get a single tag definition by ID
 */
export async function getTagDefinitionById(
  tagDefinitionId: string
): Promise<DocumentTagDefinition | null> {
  const result = await db
    .select({
      id: knowledgeBaseTagDefinitions.id,
      knowledgeBaseId: knowledgeBaseTagDefinitions.knowledgeBaseId,
      tagSlot: knowledgeBaseTagDefinitions.tagSlot,
      displayName: knowledgeBaseTagDefinitions.displayName,
      fieldType: knowledgeBaseTagDefinitions.fieldType,
      createdAt: knowledgeBaseTagDefinitions.createdAt,
      updatedAt: knowledgeBaseTagDefinitions.updatedAt,
    })
    .from(knowledgeBaseTagDefinitions)
    .where(eq(knowledgeBaseTagDefinitions.id, tagDefinitionId))
    .limit(1)

  if (result.length === 0) {
    return null
  }

  const def = result[0]
  return {
    ...def,
    tagSlot: def.tagSlot as string,
  }
}

/**
 * Update tags on all documents and chunks when a tag value is changed
 */
export async function updateTagValuesInDocumentsAndChunks(
  knowledgeBaseId: string,
  tagSlot: string,
  oldValue: string | null,
  newValue: string | null,
  requestId: string
): Promise<{ documentsUpdated: number; chunksUpdated: number }> {
  validateTagSlot(tagSlot)

  let documentsUpdated = 0
  let chunksUpdated = 0

  await db.transaction(async (tx) => {
    if (oldValue) {
      await tx
        .update(document)
        .set({
          [tagSlot]: newValue,
        })
        .where(
          and(
            eq(document.knowledgeBaseId, knowledgeBaseId),
            eq(sql.raw(`${document}.${tagSlot}`), oldValue)
          )
        )
      documentsUpdated = 1
    }

    if (oldValue) {
      await tx
        .update(embedding)
        .set({
          [tagSlot]: newValue,
        })
        .where(
          and(
            eq(embedding.knowledgeBaseId, knowledgeBaseId),
            eq(sql.raw(`${embedding}.${tagSlot}`), oldValue)
          )
        )
      chunksUpdated = 1
    }
  })

  logger.info(
    `[${requestId}] Updated tag values: ${documentsUpdated} documents, ${chunksUpdated} chunks`
  )

  return { documentsUpdated, chunksUpdated }
}

/**
 * Cleanup unused tag definitions for a knowledge base
 */
export async function cleanupUnusedTagDefinitions(
  knowledgeBaseId: string,
  requestId: string
): Promise<number> {
  const definitions = await getDocumentTagDefinitions(knowledgeBaseId)
  let cleanedUp = 0

  for (const def of definitions) {
    const tagSlot = def.tagSlot
    validateTagSlot(tagSlot)

    const docCountResult = await db
      .select({ count: sql<number>`count(*)` })
      .from(document)
      .where(
        and(
          eq(document.knowledgeBaseId, knowledgeBaseId),
          isNull(document.deletedAt),
          sql`${sql.raw(tagSlot)} IS NOT NULL`
        )
      )

    const chunkCountResult = await db
      .select({ count: sql<number>`count(*)` })
      .from(embedding)
      .where(
        and(eq(embedding.knowledgeBaseId, knowledgeBaseId), sql`${sql.raw(tagSlot)} IS NOT NULL`)
      )

    const docCount = Number(docCountResult[0]?.count || 0)
    const chunkCount = Number(chunkCountResult[0]?.count || 0)

    if (docCount === 0 && chunkCount === 0) {
      await db.delete(knowledgeBaseTagDefinitions).where(eq(knowledgeBaseTagDefinitions.id, def.id))

      cleanedUp++
      logger.info(
        `[${requestId}] Cleaned up unused tag definition: ${def.displayName} (${def.tagSlot})`
      )
    }
  }

  logger.info(`[${requestId}] Cleanup completed: ${cleanedUp} unused tag definitions removed`)
  return cleanedUp
}

/**
 * Delete all tag definitions for a knowledge base
 */
export async function deleteAllTagDefinitions(
  knowledgeBaseId: string,
  requestId: string
): Promise<number> {
  const result = await db
    .delete(knowledgeBaseTagDefinitions)
    .where(eq(knowledgeBaseTagDefinitions.knowledgeBaseId, knowledgeBaseId))
    .returning({ id: knowledgeBaseTagDefinitions.id })

  const deletedCount = result.length
  logger.info(`[${requestId}] Deleted ${deletedCount} tag definitions for KB: ${knowledgeBaseId}`)

  return deletedCount
}

/**
 * Delete a tag definition with comprehensive cleanup
 * This removes the definition and clears all document/chunk references
 */
export async function deleteTagDefinition(
  tagDefinitionId: string,
  requestId: string
): Promise<{ tagSlot: string; displayName: string }> {
  const tagDef = await db
    .select({
      id: knowledgeBaseTagDefinitions.id,
      knowledgeBaseId: knowledgeBaseTagDefinitions.knowledgeBaseId,
      tagSlot: knowledgeBaseTagDefinitions.tagSlot,
      displayName: knowledgeBaseTagDefinitions.displayName,
    })
    .from(knowledgeBaseTagDefinitions)
    .where(eq(knowledgeBaseTagDefinitions.id, tagDefinitionId))
    .limit(1)

  if (tagDef.length === 0) {
    throw new Error(`Tag definition ${tagDefinitionId} not found`)
  }

  const definition = tagDef[0]
  const knowledgeBaseId = definition.knowledgeBaseId
  const tagSlot = definition.tagSlot as string

  validateTagSlot(tagSlot)

  await db.transaction(async (tx) => {
    await tx
      .update(document)
      .set({ [tagSlot]: null })
      .where(
        and(eq(document.knowledgeBaseId, knowledgeBaseId), isNotNull(sql`${sql.raw(tagSlot)}`))
      )

    await tx
      .update(embedding)
      .set({ [tagSlot]: null })
      .where(
        and(eq(embedding.knowledgeBaseId, knowledgeBaseId), isNotNull(sql`${sql.raw(tagSlot)}`))
      )

    await tx
      .delete(knowledgeBaseTagDefinitions)
      .where(eq(knowledgeBaseTagDefinitions.id, tagDefinitionId))
  })

  logger.info(
    `[${requestId}] Deleted tag definition with cleanup: ${definition.displayName} (${tagSlot})`
  )

  return {
    tagSlot,
    displayName: definition.displayName,
  }
}

/**
 * Create a new tag definition
 */
export async function createTagDefinition(
  data: CreateTagDefinitionData,
  requestId: string
): Promise<TagDefinition> {
  const tagDefinitionId = randomUUID()
  const now = new Date()

  const newDefinition = {
    id: tagDefinitionId,
    knowledgeBaseId: data.knowledgeBaseId,
    tagSlot: data.tagSlot as ValidTagSlot,
    displayName: data.displayName,
    fieldType: data.fieldType,
    createdAt: now,
    updatedAt: now,
  }

  await db.insert(knowledgeBaseTagDefinitions).values(newDefinition)

  logger.info(
    `[${requestId}] Created tag definition: ${data.displayName} -> ${data.tagSlot} in KB ${data.knowledgeBaseId}`
  )

  return {
    id: tagDefinitionId,
    tagSlot: data.tagSlot,
    displayName: data.displayName,
    fieldType: data.fieldType,
    createdAt: now,
    updatedAt: now,
  }
}

/**
 * Update an existing tag definition
 */
export async function updateTagDefinition(
  tagDefinitionId: string,
  data: UpdateTagDefinitionData,
  requestId: string
): Promise<TagDefinition> {
  const now = new Date()

  const updateData: {
    updatedAt: Date
    displayName?: string
    fieldType?: string
  } = {
    updatedAt: now,
  }

  if (data.displayName !== undefined) {
    updateData.displayName = data.displayName
  }

  if (data.fieldType !== undefined) {
    updateData.fieldType = data.fieldType
  }

  const updatedRows = await db
    .update(knowledgeBaseTagDefinitions)
    .set(updateData)
    .where(eq(knowledgeBaseTagDefinitions.id, tagDefinitionId))
    .returning({
      id: knowledgeBaseTagDefinitions.id,
      tagSlot: knowledgeBaseTagDefinitions.tagSlot,
      displayName: knowledgeBaseTagDefinitions.displayName,
      fieldType: knowledgeBaseTagDefinitions.fieldType,
      createdAt: knowledgeBaseTagDefinitions.createdAt,
      updatedAt: knowledgeBaseTagDefinitions.updatedAt,
    })

  if (updatedRows.length === 0) {
    throw new Error(`Tag definition ${tagDefinitionId} not found`)
  }

  const updated = updatedRows[0]
  logger.info(`[${requestId}] Updated tag definition: ${tagDefinitionId}`)

  return {
    ...updated,
    tagSlot: updated.tagSlot as string,
  }
}

/**
 * Get tag usage with detailed document information (original format)
 */
export async function getTagUsage(
  knowledgeBaseId: string,
  requestId = 'api'
): Promise<
  Array<{
    tagName: string
    tagSlot: string
    documentCount: number
    documents: Array<{ id: string; name: string; tagValue: string }>
  }>
> {
  const definitions = await getDocumentTagDefinitions(knowledgeBaseId)
  const usage = []

  for (const def of definitions) {
    const tagSlot = def.tagSlot
    validateTagSlot(tagSlot)

    // Build WHERE conditions based on field type
    // Text columns need both IS NOT NULL and != '' checks
    // Numeric/date/boolean columns only need IS NOT NULL
    const fieldType = getFieldTypeForSlot(tagSlot)
    const isTextColumn = fieldType === 'text'

    const whereConditions = [
      eq(document.knowledgeBaseId, knowledgeBaseId),
      isNull(document.deletedAt),
      isNotNull(sql`${sql.raw(tagSlot)}`),
    ]

    // Only add empty string check for text columns
    if (isTextColumn) {
      whereConditions.push(sql`${sql.raw(tagSlot)} != ''`)
    }

    const documentsWithTag = await db
      .select({
        id: document.id,
        filename: document.filename,
        tagValue: sql<string>`${sql.raw(tagSlot)}::text`,
      })
      .from(document)
      .where(and(...whereConditions))

    usage.push({
      tagName: def.displayName,
      tagSlot: def.tagSlot,
      documentCount: documentsWithTag.length,
      documents: documentsWithTag.map((doc) => ({
        id: doc.id,
        name: doc.filename,
        tagValue: doc.tagValue || '',
      })),
    })
  }

  logger.info(`[${requestId}] Retrieved detailed tag usage for ${usage.length} definitions`)

  return usage
}

/**
 * Get tag usage statistics
 */
export async function getTagUsageStats(
  knowledgeBaseId: string,
  requestId: string
): Promise<
  Array<{
    tagSlot: string
    displayName: string
    fieldType: string
    documentCount: number
    chunkCount: number
  }>
> {
  const definitions = await getDocumentTagDefinitions(knowledgeBaseId)
  const stats = []

  for (const def of definitions) {
    const tagSlot = def.tagSlot
    validateTagSlot(tagSlot)

    const docCountResult = await db
      .select({ count: sql<number>`count(*)` })
      .from(document)
      .where(
        and(
          eq(document.knowledgeBaseId, knowledgeBaseId),
          isNull(document.deletedAt),
          sql`${sql.raw(tagSlot)} IS NOT NULL`
        )
      )

    const chunkCountResult = await db
      .select({ count: sql<number>`count(*)` })
      .from(embedding)
      .where(
        and(eq(embedding.knowledgeBaseId, knowledgeBaseId), sql`${sql.raw(tagSlot)} IS NOT NULL`)
      )

    stats.push({
      tagSlot: def.tagSlot,
      displayName: def.displayName,
      fieldType: def.fieldType,
      documentCount: Number(docCountResult[0]?.count || 0),
      chunkCount: Number(chunkCountResult[0]?.count || 0),
    })
  }

  logger.info(`[${requestId}] Retrieved tag usage stats for ${stats.length} definitions`)

  return stats
}

